import java.io.*;
import java.util.*;

public class Test {
    static PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    long[][] binom = new long[61][61];
    int[] cntA = new int[61], cntB = new int[61];
    long best = Long.MAX_VALUE;
    String s;
    Map<Long, Long> memo = new HashMap<>();
    Set<Long> visited = new HashSet<>();

    public static void main(String[] args) {
        new Test().start();
        out.flush();
    }

    static int readInt() {
        int ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = System.in.read()) != -1) {
                if (c == '-') { start = true; neg = true; continue; }
                if (c >= '0' && c <= '9') { start = true; ans = ans * 10 + (c - '0'); }
                else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    static long readLong() {
        long ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = System.in.read()) != -1) {
                if (c == '-') { start = true; neg = true; continue; }
                if (c >= '0' && c <= '9') { start = true; ans = ans * 10 + (c - '0'); }
                else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    static String readString() {
        StringBuilder sb = new StringBuilder();
        try {
            boolean start = false;
            int c;
            while ((c = System.in.read()) != -1) {
                if (!Character.isWhitespace(c)) { start = true; sb.append((char) c); }
                else if (start) break;
            }
        } catch (IOException e) {}
        return sb.toString();
    }

    static int readChars(char[] a, int off) {
        int cnt = 0;
        try {
            boolean start = false;
            int c;
            while ((c = System.in.read()) != -1) {
                if (Character.isLetterOrDigit(c)) { start = true; a[off + cnt++] = (char) c; }
                else if (start) break;
            }
        } catch (IOException e) {}
        return cnt;
    }

    // Iterative version of dfs using explicit stack
    void dfsIter(long x, long y, int v1, int v2) {
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{x, y, v1, v2, 0}); // 0 = entry, 1 = after first child, etc.
        while (!stack.isEmpty()) {
            long[] state = stack.pop();
            long a = state[0], b = state[1];
            int i = (int) state[2], j = (int) state[3];
            int phase = (int) state[4];
            long diff = Math.abs(a - b);
            if (best <= 1 || diff - binom[i][R] * binom[j][R] >= best) continue;
            if (i == R - 1 && j == R - 1) {
                if (diff < best) best = diff;
                continue;
            }
            long key = a * 10000 + i * 100 + j;
            if (visited.contains(key)) continue;
            if (phase == 0) {
                visited.add(key);
                // Push current state to resume after children
                stack.push(new long[]{a, b, i, j, 1});
                if (i >= R) {
                    long cur = binom[i][R] - binom[i - 1][R];
                    long other = binom[j][R];
                    stack.push(new long[]{a, b + cur * other, i - 1, j, 0});
                }
                if (j >= R) {
                    long cur = binom[j][R] - binom[j - 1][R];
                    long other = binom[i][R];
                    stack.push(new long[]{a + cur * other, b, i, j - 1, 0});
                }
            }
            // phase 1: nothing to do after children
        }
    }

    // Iterative version of solve using explicit stack
    long solveIter(long x, long y, int v1, int v2) {
        Deque<Object[]> stack = new ArrayDeque<>();
        stack.push(new Object[]{x, y, v1, v2, 0, null}); // last element for result placeholder
        long result = 0;
        while (!stack.isEmpty()) {
            Object[] state = stack.pop();
            long a = (long) state[0], b = (long) state[1];
            int i = (int) state[2], j = (int) state[3];
            int phase = (int) state[4];
            Long childRes = (Long) state[5];
            long diff = Math.abs(a - b);
            if (diff - binom[i][R] * binom[j][R] > best) continue;
            long key = a * 10000 + i * 100 + j;
            if (phase == 0) {
                Long cached = memo.get(key);
                if (cached != null) {
                    result = cached;
                    continue;
                }
                if (i < R || j < R) {
                    if (i >= cntA[i + j] && j >= cntB[i + j]) {
                        int sum = i + j;
                        i -= cntA[sum];
                        j -= cntB[sum];
                        result = binom[i + j][i];
                        memo.put(key, result);
                        continue;
                    }
                    result = 0;
                    memo.put(key, result);
                    continue;
                }
                // Push current state to collect children results
                stack.push(new Object[]{a, b, i, j, 1, null});
                char c = s.charAt(i + j - 1);
                if (c != 'B') {
                    long cur = binom[i][R] - binom[i - 1][R];
                    long other = binom[j][R];
                    stack.push(new Object[]{a, b + cur * other, i - 1, j, 0, null});
                }
                if (c != 'A') {
                    long cur = binom[j][R] - binom[j - 1][R];
                    long other = binom[i][R];
                    stack.push(new Object[]{a + cur * other, b, i, j - 1, 0, null});
                }
            } else {
                // phase 1: combine children results
                long ans = 0;
                // We need to collect results from children; but we only have one childRes from the last child?
                // This approach is flawed. Instead, we should use a different iterative pattern.
                // For simplicity, we revert to recursion for solve in this variant.
                // Actually, we'll keep solve recursive and only make dfs iterative.
                // So we'll call the original solve recursively.
                // But to maintain consistency, we'll implement solve recursively.
                // So this variant will have iterative dfs but recursive solve.
                // That's fine.
            }
        }
        return result;
    }

    // Keep solve recursive for simplicity
    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - binom[v1][R] * binom[v2][R] > best) return 0;
        long key = x * 10000 + v1 * 100 + v2;
        Long v = memo.get(key);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return binom[v1 + v2][v1];
            }
            return 0;
        }
        long ans = 0;
        char c = s.charAt(v1 + v2 - 1);
        if (c != 'B') {
            long cur = binom[v1][R] - binom[v1 - 1][R];
            long other = binom[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long cur = binom[v2][R] - binom[v2 - 1][R];
            long other = binom[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        memo.put(key, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        for (int i = 0; i <= maxN; i++) {
            binom[i][0] = binom[i][i] = 1;
            for (int j = 1; j < i; j++)
                binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
        }
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R) {
            if (x > y) {
                long cur = binom[v1][R] - binom[v1 - 1][R];
                long other = binom[v2][R];
                y += cur * other;
                v1--;
            } else {
                long cur = binom[v2][R] - binom[v2 - 1][R];
                long other = binom[v1][R];
                x += cur * other;
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfsIter(0, 0, R + C, R + C);
        s = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (s.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (s.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        out.println(ans);
    }
}
